import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Port mapping library","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/port-mapping/docs/index.md"},"headers":[],"relativePath":"tools/port-mapping/docs/index.md","filePath":"tools/port-mapping/docs/index.md","lastUpdated":1792252169000}`),a={name:`tools/port-mapping/docs/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="port-mapping-library" tabindex="-1">Port mapping library <a class="header-anchor" href="#port-mapping-library" aria-label="Permalink to “Port mapping library”">​</a></h1><p><code>@pumpkin-plugins/port-mapping</code> finds a router that supports UPnP or NAT-PMP and keeps requested ports open on it. The library has no Pumpkin or WASI dependency, so a host can use it by providing the network operations through its <code>Network</code> interface.</p><h2 id="requesting-a-mapping" tabindex="-1">Requesting a mapping <a class="header-anchor" href="#requesting-a-mapping" aria-label="Permalink to “Requesting a mapping”">​</a></h2><p>Create a <code>PortMapper</code> with a <code>Network</code> adapter and mapper options, then call <code>request</code> with a key and a mapping specification. The key lets you check or release that request later. A request starts as <code>pending</code>; call <code>tick</code> regularly to advance discovery and network work, then read its state to learn whether it opened or failed. An open state includes the address and external port to use. If the router cannot use the requested external port, the mapper tries another one. Call <code>release</code> when the port is no longer needed; the router is told to close it on a later tick. During shutdown, use <code>releaseAll</code> and let it finish so the mapper can clean up its open ports.</p><p>The mapper renews a lease halfway through its lifetime. If discovery or a mapping operation fails, it retries with increasing delays and searches for the router again. A machine with its own public address does not need a router mapping; the mapper reports that address directly. If the router&#39;s internet-side address is not public, such as behind carrier-grade NAT, an inbound mapping cannot make the server reachable.</p><h2 id="network-adapter-and-router-screening" tabindex="-1">Network adapter and router screening <a class="header-anchor" href="#network-adapter-and-router-screening" aria-label="Permalink to “Network adapter and router screening”">​</a></h2><p>The <code>Network</code> adapter supplies the operations the host needs: opening UDP datagrams, dialing TCP, finding the local address used to reach a destination, and reading the current time. These operations return promptly rather than waiting for network activity. The mapper advances the resulting work through <code>tick</code>, so callers can make progress without blocking a game tick.</p><p>When both protocols are enabled, the UPnP SSDP search and device-description reads finish before NAT-PMP discovery starts. The UPnP SOAP and NAT-PMP requests then run together, and UPnP is preferred when both find a router. If you provide a router-identification <code>screen</code>, the library probes the router&#39;s web interface first, then checks UPnP descriptions before sending protocol requests. A screen can refuse routers it recognizes as unsupported; routers that cannot be identified are left alone.</p><p>The package includes fake network and router implementations for deterministic tests. They let you exercise discovery and mapping behavior without a live router.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};